'use strict';
// Photos are bundled below so the existing Docker COPY remains unchanged.
// Regenerate this block with: python frontend/tools/bundle_images.py
/* PRODUCT_IMAGES_START */
const PRODUCT_IMAGES = Object.freeze({
  "p1": "data:image/jpeg;base64,",
  "p2": "data:image/jpeg;base64,",
  "p3": "data:image/jpeg;base64,",
  "p4": "data:image/jpeg;base64,",
  "p5": "data:image/jpeg;base64,",
  "p6": "data:image/jpeg;base64,",
  "p7": "data:image/jpeg;base64,",
  "p8": "data:image/jpeg;base64,",
  "p9": "data:image/jpeg;base64,",
  "p10": "data:image/jpeg;base64,",
  "p11": "data:image/jpeg;base64,",
  "p12": "data:image/jpeg;base64,"
});
/* PRODUCT_IMAGES_END */

const $ = id => document.getElementById(id);
const savedUser = localStorage.getItem('affinity.activeUser') || 'student1';

const state = {catalog: [], activeUser: savedUser, category: '', generation: 0,
  recRequest: 0, historyRequest: 0, systemRequest: 0, analyticsRequest: 0,
  refreshSequence: 0,
  history: [], offset: 0, pageSize: 50, pending: new Map(), busy: new Set()};
  // Recommendation update tracking
let lastSignalVersion = null;
let lastSignalUser = null;
let recPollBusy = false;
const icons = {
  discover: '<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',
  history: '<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v5l3 2"/>',
  analytics: '<path d="M4 20h16M7 16v-5M12 16V4M17 16V8"/>',
  system: '<rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01M14 6.5h3M14 17.5h3"/>',
  search: '<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',
  refresh: '<path d="M20 7a9 9 0 0 0-15 0M4 3v5h5M4 17a9 9 0 0 0 15 0M20 21v-5h-5"/>',
  spark: '<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5Z"/>',
  view: '<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
  click: '<path d="m5 3 14 10-7 1-3 7Z"/>',
  purchase: '<path d="M5 8h14l1 13H4ZM8 8V6a4 4 0 0 1 8 0v2"/>',
  info: '<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>'
};
function element(tag, text, cls) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  if (cls) node.className = cls;
  return node;
}
function icon(name) {
  const span = element('span');
  // All SVG paths are application constants, never API content.
  span.innerHTML = '<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">' + (icons[name] || icons.info) + '</svg>';
  return span.firstElementChild;
}
function message(text, error = false) {
  $('message').textContent = text;
  $('message').className = error ? 'error' : '';
}
function title(text) { return text ? text[0].toUpperCase() + text.slice(1).replaceAll('_', ' ') : ''; }
function price(value) { return Number.isFinite(value) ? '₹' + value.toLocaleString('en-IN') : 'Price unavailable'; }
async function request(path, options = {}) {
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 15000);
  try {
    const response = await fetch('/api' + path, {...options, signal: controller.signal});
    if (!response.ok) {
      let body; try { body = await response.json(); } catch {}
      const detail = typeof body?.detail === 'string' ? body.detail : 'HTTP ' + response.status;
      throw Error(detail);
    }
    return await response.json();
  } catch (error) {
    if (error.name === 'AbortError') throw Error('The request timed out. Please retry.');
    throw error;
  } finally { clearTimeout(timeout); }
}
function empty(container, heading, description, retry) {
  const panel = element('div', undefined, 'empty-state');
  panel.append(element('h3', heading), element('p', description));
  if (retry) { const button = element('button', 'Try again', 'secondary'); button.onclick = retry; panel.append(button); }
  $(container).replaceChildren(panel);
}
function loading(container, text) {
  $(container).setAttribute('aria-busy', 'true');
  $(container).replaceChildren(element('div', text, 'loading-state'));
}
function loaded(container) { $(container).setAttribute('aria-busy', 'false'); }
function failure(container, error, retry) {
  loaded(container);
  empty(container, 'Couldn’t load this just yet.', error.message + ' You can try again.', retry);
}
function productImage(product) {
  const media = element('div', undefined, 'product-media');
  const photo = PRODUCT_IMAGES[product.id];
  const fallback = () => {
    const text = element('div', undefined, 'image-fallback');
    text.append(element('strong', product.name), element('small', 'Photograph unavailable'));
    media.replaceChildren(text);
  };
  if (!photo) { fallback(); return media; }
  const img = element('img');
  img.alt = product.name + ' — product photograph';
  img.width = 720; img.height = 540; img.loading = 'lazy'; img.decoding = 'async';
  img.onerror = fallback; img.src = photo;
  media.append(img); return media;
}
function eventKey(productId, kind, user = state.activeUser) { return JSON.stringify([user, productId, kind]); }
function updateActionButtons(key) {
  for (const button of document.querySelectorAll('[data-event-key]')) {
    if (button.dataset.eventKey !== key) continue;
    button.disabled = state.busy.has(key);
    const label = state.busy.has(key) ? 'Saving…' : (state.pending.has(key) ? 'Retry ' : '') + title(button.dataset.kind);
    button.replaceChildren(icon(button.dataset.kind), document.createTextNode(label));
  }
}
function card(input, explain = false) {
  // Merge catalogue fields only; recommendation score/reasons always come from API.
  const product = {...state.catalog.find(p => p.id === input.id), ...input};
  const node = element('article', undefined, 'card'); node.dataset.productId = product.id;
  node.append(productImage(product));
  const body = element('div', undefined, 'card-body');
  body.append(element('small', title(product.category), 'category-label'), element('h3', product.name));
  const pricing = element('div', undefined, 'price-line'); pricing.append(element('span', price(product.price), 'price'));
  if (explain && Number.isFinite(product.score)) {
    const score = element('span', 'Score ' + product.score.toFixed(3), 'score');
    score.title = 'Backend ranking score, not a probability'; pricing.append(score);
  }
  body.append(pricing);
  const actions = element('div', undefined, 'actions');
  for (const kind of ['view', 'click', 'purchase']) {
    const button = element('button'); button.type = 'button';
    button.dataset.eventKey = eventKey(product.id, kind); button.dataset.kind = kind;
    button.append(icon(kind), document.createTextNode((state.pending.has(button.dataset.eventKey) ? 'Retry ' : '') + title(kind)));
    button.disabled = state.busy.has(button.dataset.eventKey);
    button.setAttribute('aria-label', title(kind) + ' ' + product.name);
    button.onclick = () => act(product.id, kind, node);
    actions.append(button);
  }
  body.append(actions);
  const feedback = element('p', '', 'event-feedback'); feedback.setAttribute('role', 'status'); body.append(feedback);
  if (explain) {
    const details = element('details', undefined, 'explanation');
    details.append(element('summary', 'Why this?'));
    const reasons = product.explanation?.reasons;
    if (Array.isArray(reasons) && reasons.length) {
      for (const reason of reasons) details.append(element('p', String(reason)));
    } else details.append(element('p', 'No explanation was provided by the recommendation service.'));
    const contributions = product.explanation?.contributions;
    if (contributions && typeof contributions === 'object') {
      for (const [name, value] of Object.entries(contributions)) {
        if (!Number.isFinite(value)) continue;
        const row = element('div', undefined, 'contribution-row');
        row.append(element('span', title(name)), element('span', value.toFixed(4)));
        const bar = element('div', undefined, 'bar'), fill = element('span');
        fill.style.width = Math.max(0, Math.min(100, value * 100)) + '%'; bar.append(fill); details.append(row, bar);
      }
    }
    if (Number.isFinite(product.score)) details.append(element('p', 'Ranking score ' + product.score.toFixed(4) + ' · not a probability.'));
    body.append(details);
  }
  node.append(body); return node;
}
function render(container, items, explain = false) {
  $(container).replaceChildren(...items.map(p => card(p, explain))); loaded(container);
  if (!items.length) empty(container, explain ? 'Your next discovery is on its way.' : 'Nothing here just yet.', explain ? 'Explore the collection and record an interaction, then refresh your recommendations.' : 'Try another search or check back after more activity.');
}


async function recommendations(forceRefresh = false) {

  const ticket = ++state.recRequest;
  const generation = state.generation;
  const user = state.activeUser;

  loading('recs', 'Finding recommendations for ' + user + '…');
  $('refresh').disabled = true;

  try {

    const refresh = forceRefresh ? ++state.refreshSequence : 0;
    const data = await request(
      '/recommendations/' + encodeURIComponent(user) +
      (refresh ? '?refresh=' + refresh : '')
    );

    if (
      ticket !== state.recRequest ||
      generation !== state.generation
    ) {
      return;
    }

    if (!Array.isArray(data.recommendations)) {
      throw Error('Unexpected recommendation response');
    }

    // Save the latest backend signal version.
    if (Number.isFinite(Number(data.signal_version))) {
      lastSignalVersion = Number(data.signal_version);
      lastSignalUser = user;
    }

    // Display recommendations without changing the UI.
    render('recs', data.recommendations, true);

  } catch (error) {

    if (
      ticket === state.recRequest &&
      generation === state.generation
    ) {
      failure('recs', error, recommendations);
    }

  } finally {

    if (ticket === state.recRequest) {
      $('refresh').disabled = false;
    }
  }
}

async function pollRecommendationUpdates() {

  if (recPollBusy || document.hidden) {
    return;
  }

  recPollBusy = true;

  const user = state.activeUser;
  const generation = state.generation;

  try {

    const data = await request(
      '/recommendations/' + encodeURIComponent(user)
    );

    // Do not display results belonging to another profile.
    if (
      user !== state.activeUser ||
      generation !== state.generation
    ) {
      return;
    }

    if (!Array.isArray(data.recommendations)) {
      return;
    }

    const newVersion = Number(data.signal_version);

    if (!Number.isFinite(newVersion)) {
      return;
    }

    // Update the UI only when backend data has changed.
    if (
      lastSignalUser !== user ||
      lastSignalVersion !== newVersion
    ) {

      lastSignalUser = user;
      lastSignalVersion = newVersion;

      render(
        'recs',
        data.recommendations,
        true
      );
    }

  } catch (error) {

    console.warn(
      'Recommendation background update failed:',
      error
    );

  } finally {

    recPollBusy = false;
  }
}

async function act(productId, kind, cardNode) {
  const user = state.activeUser, key = eventKey(productId, kind, user);
  if (state.busy.has(key)) return;
  let payload = state.pending.get(key);
  if (!payload) {
    payload = {event_id: crypto.randomUUID(), user_id: user, product_id: productId, event_type: kind, dwell_seconds: 0};
    state.pending.set(key, payload);
  }
  state.busy.add(key); updateActionButtons(key);
  const feedback = cardNode.querySelector('.event-feedback'); feedback.textContent = 'Saving interaction…'; feedback.className = 'event-feedback';
  try {
    await request('/events', {method: 'POST', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(payload)});
    state.pending.delete(key);
    if (user === state.activeUser) {
      feedback.textContent = title(kind) + ' recorded.';
      message(title(kind) + ' recorded. Recommendations are being refreshed using your latest activity.');
      // Recommendation errors stay in their panel; they cannot change the committed event outcome.
      recommendations();
      if (!$('history').hidden) loadHistory(true);
    }
  } catch (error) {
    if (user === state.activeUser) {
      feedback.textContent = 'Not confirmed: ' + error.message + ' Retry safely using the same event ID.';
      feedback.className = 'event-feedback error'; message('Request failed: ' + error.message, true);
    }
  } finally { state.busy.delete(key); updateActionButtons(key); }
}
function filter() {
  const query = $('search').value.trim().toLowerCase();
  const products = state.catalog.filter(p => (!state.category || p.category === state.category) && (p.name + ' ' + (p.tags || '')).toLowerCase().includes(query));
  render('products', products);
  $('productCount').textContent = products.length + ' of ' + state.catalog.length + ' products';
  for (const button of $('categories').querySelectorAll('button')) button.setAttribute('aria-pressed', String(button.dataset.category === state.category));
  if (!products.length) empty('products', 'No matching finds.', 'Try a different word or browse all categories.', () => { state.category = ''; $('search').value = ''; filter(); });
}
async function loadCatalog() {
  loading('products', 'Opening the collection…');
  try {
    const data = await request('/products');
    if (!Array.isArray(data)) throw Error('Unexpected catalogue response');
    state.catalog = data;
    $('categories').replaceChildren();
    for (const category of ['', ...new Set(data.map(p => p.category))]) {
      const button = element('button', category ? title(category) : 'All products'); button.dataset.category = category;
      button.onclick = () => { state.category = category; filter(); }; $('categories').append(button);
    }
    filter();
    const hero = state.catalog.find(p => p.id === 'p2');
    if (hero) { const media = productImage(hero); const img = media.querySelector('img'); if (img) { img.loading = 'eager'; img.onerror = () => img.replaceWith(element('span', hero.name, 'hero-image-fallback')); $('heroVisual').append(img); } }
  } catch (error) { failure('products', error, loadCatalog); }
}
async function trending() {
  $('trendingRefresh').disabled = true; loading('trending', 'Loading popular finds…');
  try { const items = await request('/trending'); if (!Array.isArray(items)) throw Error('Unexpected trending response'); render('trending', items); }
  catch (error) { failure('trending', error, trending); }
  finally { $('trendingRefresh').disabled = false; }
}
function renderHistory() {
  const kind = $('activityType').value, rows = state.history.filter(r => !kind || r.event_type === kind);
  $('historyRows').replaceChildren(...rows.map(row => {
    const node = element('div', undefined, 'history-row');
    const badge = element('span', undefined, 'activity-icon ' + row.event_type); badge.append(icon(row.event_type));
    const text = element('div'); text.append(element('strong', state.catalog.find(p => p.id === row.product_id)?.name || row.product_id), element('p', title(row.event_type) + ' interaction'));
    const date = new Date(row.created_at), time = element('time', Number.isNaN(date.getTime()) ? 'Timestamp unavailable' : date.toLocaleString());
    if (!Number.isNaN(date.getTime())) time.dateTime = date.toISOString();
    node.append(badge, text, time); return node;
  }));
  if (!rows.length) empty('historyRows', state.history.length ? 'No matching interactions on this page.' : 'A fresh start.', state.history.length ? 'Choose another filter or browse the next page.' : 'Explore a product to start your discovery timeline.');
  $('historyCount').textContent = state.history.length ? 'Records ' + (state.offset + 1) + '–' + (state.offset + state.history.length) + ' · ' + rows.length + ' shown' : 'No records on this page';
  $('historyPrev').disabled = state.offset === 0; $('historyNext').disabled = state.history.length < state.pageSize;
}
async function loadHistory(reset = false) {
  if (reset) state.offset = 0;
  const ticket = ++state.historyRequest, generation = state.generation, user = state.activeUser;
  state.history = []; loading('historyRows', 'Loading your activity…');
  $('historyPrev').disabled = $('historyNext').disabled = $('historyRefresh').disabled = true; $('historyCount').textContent = '';
  try {
    const rows = await request('/events/' + encodeURIComponent(user) + '?limit=' + state.pageSize + '&offset=' + state.offset);
    if (ticket !== state.historyRequest || generation !== state.generation) return;
    if (!Array.isArray(rows)) throw Error('Unexpected activity response');
    state.history = rows; loaded('historyRows'); renderHistory();
  } catch (error) {
    if (ticket === state.historyRequest && generation === state.generation) { failure('historyRows', error, () => loadHistory()); $('historyPrev').disabled = state.offset === 0; }
  } finally { if (ticket === state.historyRequest) $('historyRefresh').disabled = false; }
}
const serviceLabels = {api: ['API', 'Application requests and event acceptance.'], database: ['PostgreSQL', 'Shared persistence and database readiness.'], redis: ['Redis', 'Recommendation cache availability.'], recommendation: ['Recommendation service', 'Personalised ranking service readiness.']};
function renderHealth(data) {
  $('health').replaceChildren(...Object.entries(serviceLabels).map(([key, [name, description]]) => {
    const value = data[key], status = value === 'up' ? 'up' : value === 'down' ? 'down' : 'unknown';
    const node = element('article', undefined, 'health-card'), top = element('div', undefined, 'health-card-top');
    top.append(icon(key === 'recommendation' ? 'spark' : 'system'), element('span', status === 'unknown' ? (value === 'degraded' ? 'Degraded' : 'Unknown') : title(status), 'status ' + status));
    node.append(top, element('h3', name), element('p', description)); return node;
  }));
}
async function system() {
  const ticket = ++state.systemRequest; $('systemRefresh').disabled = true;
  renderHealth({}); $('health').setAttribute('aria-busy', 'true'); $('healthUpdated').textContent = 'Checking services…';
  try {
    const data = await request('/system'); if (ticket !== state.systemRequest) return;
    renderHealth(data); $('healthUpdated').textContent = 'Last checked ' + new Date().toLocaleString();
  } catch (error) {
    if (ticket !== state.systemRequest) return;
    renderHealth({}); $('healthUpdated').textContent = 'Check unavailable: ' + error.message + '. Refresh to retry.';
    message('Request failed: ' + error.message, true);
  } finally { if (ticket === state.systemRequest) { $('systemRefresh').disabled = false; loaded('health'); } }
}
function chart(heading, entries, note) {
  const panel = element('div', undefined, 'panel'); panel.append(element('h2', heading));
  const maximum = Math.max(1, ...entries.map(([, value]) => Number.isFinite(value) ? value : 0));
  for (const [name, value] of entries) {
    const row = element('div', undefined, 'chart-row'), label = element('div', undefined, 'chart-label');
    label.append(element('span', name), element('strong', Number.isFinite(value) ? value.toLocaleString() : 'Unavailable'));
    const bar = element('div', undefined, 'bar'), fill = element('span'); fill.style.width = (Number.isFinite(value) ? Math.max(0, value / maximum * 100) : 0) + '%'; bar.append(fill); row.append(label, bar); panel.append(row);
  }
  panel.append(element('p', note, 'fineprint')); return panel;
}
async function analytics() {
  const ticket = ++state.analyticsRequest; $('adminLoad').disabled = true;
  loading('stats', 'Loading workspace analytics…'); $('charts').replaceChildren(); $('analyticsUpdated').textContent = '';
  try {
    const data = await request('/admin/analytics', {headers: {'X-Admin-Key': $('adminKey').value}});
    if (ticket !== state.analyticsRequest) return;
    const definitions = [['events', 'Total events', 'Accepted events in the database'], ['processed', 'Processed events', 'Consumer processing ledger'], ['pending', 'Pending events', 'Outbox records awaiting publication'], ['dead_letters', 'Dead-letter events', 'Records retained for inspection'], ['users', 'Demo users', 'Distinct users with recorded events']];
    const types = data.types && typeof data.types === 'object' ? data.types : null;
    const metrics = definitions.map(([key, label, help]) => [label, data[key], help]);
    metrics.push(['Interaction types', types ? Object.keys(types).length : undefined, 'Recorded event categories']);
    $('stats').replaceChildren(...metrics.map(([label, value, help]) => {
      const node = element('div', undefined, 'kpi'); node.append(element('small', label), element('strong', Number.isFinite(value) ? value.toLocaleString() : '—', 'kpi-value'), element('p', help)); return node;
    })); loaded('stats');
    const breakdown = types ? [...new Set(['view', 'click', 'purchase', ...Object.keys(types)])].map(kind => [title(kind), types[kind] ?? 0]) : [['Views', undefined], ['Clicks', undefined], ['Purchases', undefined]];
    $('charts').append(chart('What catches their eye', breakdown, 'Interaction counts from the analytics API.'), chart('Event processing overview', [['Accepted', data.events], ['Processed', data.processed], ['Pending publication', data.pending], ['Dead letters', data.dead_letters]], 'Independent counts, not parts of one total. Published events can still await consumer processing.'));
    $('analyticsUpdated').textContent = 'Snapshot loaded ' + new Date().toLocaleString() + ' · Refresh using Load analytics.';
  } catch (error) { if (ticket === state.analyticsRequest) failure('stats', error, analytics); }
  finally { if (ticket === state.analyticsRequest) $('adminLoad').disabled = false; }
}
function navigate(tab) {
  if (!['discover', 'history', 'analytics', 'system'].includes(tab)) tab = 'discover';
  const names = {discover: 'Discover', history: 'Your Activity', analytics: 'Admin Analytics', system: 'System Health'};
  for (const id of Object.keys(names)) $(id).hidden = id !== tab;
  for (const button of document.querySelectorAll('[data-tab]')) {
    const active = button.dataset.tab === tab; button.classList.toggle('active', active);
    if (active) button.setAttribute('aria-current', 'page'); else button.removeAttribute('aria-current');
  }
  $('breadcrumb').textContent = 'Workspace / ' + names[tab]; message('');
  if (tab === 'history') loadHistory(true);
  if (tab === 'system') system();
}
for (const target of document.querySelectorAll('[data-icon]')) target.replaceWith(icon(target.dataset.icon));
for (const button of document.querySelectorAll('[data-tab]')) button.onclick = () => { window.location.hash = button.dataset.tab; };

// Restore the previously selected student profile
$('user').value = state.activeUser;
document.querySelector('.avatar').textContent =
    state.activeUser[0].toUpperCase();

window.addEventListener('hashchange', () => { if (window.location.hash !== '#collection') navigate(window.location.hash.slice(1)); });
$('profileForm').onsubmit = event => {
  event.preventDefault(); const user = $('user').value.trim();
  if (!user) { message('Enter a demo profile name.', true); return; }
  state.activeUser = user;
localStorage.setItem('affinity.activeUser', user);

state.generation++;
state.offset = 0;
state.history = [];
  $('user').value = user; document.querySelector('.avatar').textContent = user[0].toUpperCase();
  message('Profile switched to ' + user + '.'); filter(); recommendations(); trending();
  $('historyRows').replaceChildren(); if (!$('history').hidden) loadHistory(true);
};
$('adminForm').onsubmit = event => { event.preventDefault(); analytics(); };
$('refresh').onclick = () => recommendations(true); $('search').oninput = filter; $('trendingRefresh').onclick = trending;
$('historyRefresh').onclick = () => loadHistory(true); $('activityType').onchange = renderHistory;
$('historyPrev').onclick = () => { state.offset = Math.max(0, state.offset - state.pageSize); loadHistory(); };
$('historyNext').onclick = () => { state.offset += state.pageSize; loadHistory(); };
$('systemRefresh').onclick = system;
empty('stats', 'Your workspace, in focus.', 'Enter your admin key to load real event counts.'); renderHealth({});
(async () => { await loadCatalog(); recommendations(); trending(); navigate(window.location.hash.slice(1)); })();
(async () => {// Automatically check for new recommendation signals every 3 seconds.
setInterval(pollRecommendationUpdates, 3000);})();